package com.thakur.employee.exception; import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*; @RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){var errors=new HashMap<String,String>();e.getBindingResult().getFieldErrors().forEach(x->errors.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"message","Validation failed","errors",errors));}@ExceptionHandler({IllegalArgumentException.class,NoSuchElementException.class}) ResponseEntity<?> bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"message",e.getMessage()==null?"Request failed":e.getMessage()));}}
